new file mode 100644
index 0000000..b3d6ba8
--- /dev/null
+++ b/crates/ignore/tests/parallel_visitor_panic.rs
@@ -0,0 +1,80 @@
+// Reproduction for "ignore: parallel walker occasionally hangs if visitor
+// panics" (BurntSushi/ripgrep#3009).
+//
+// Expected (from the report): `WalkParallel::run()` / `visit()` must not hang
+// when the visitor panics; the panic should be propagated to the caller.
+//
+// This is the reporter's `panic_in_parallel` test, written against the public
+// API only (so no production code is touched), with a watchdog so that a hang
+// shows up as a test failure (non-zero exit) rather than an endless run.
+
+use std::any::Any;
+use std::fs;
+use std::panic::{self, AssertUnwindSafe};
+use std::sync::mpsc::{self, RecvTimeoutError};
+use std::time::Duration;
+
+use ignore::WalkBuilder;
+
+/// Generous: the walk below takes a few milliseconds when it works.
+const HANG_TIMEOUT: Duration = Duration::from_secs(10);
+
+fn payload_message(payload: &(dyn Any + Send)) -> String {
+    if let Some(s) = payload.downcast_ref::<&'static str>() {
+        s.to_string()
+    } else if let Some(s) = payload.downcast_ref::<String>() {
+        s.clone()
+    } else {
+        "<non-string panic payload>".to_string()
+    }
+}
+
+#[test]
+fn panic_in_parallel_does_not_hang() {
+    // Own temp dir (the crate's internal `TempDir` helper is not reachable
+    // from an integration test and gives up once /tmp/rust-ignore/0..99 are
+    // taken by leftovers of earlier, killed runs).
+    let dir = std::env::temp_dir()
+        .join(format!("ignore-panic-in-parallel-{}", std::process::id()));
+    fs::create_dir_all(&dir).unwrap();
+    fs::write(dir.join("foo.txt"), "").unwrap();
+
+    let (tx, rx) = mpsc::channel();
+    let walk_dir = dir.clone();
+    std::thread::spawn(move || {
+        let result = panic::catch_unwind(AssertUnwindSafe(|| {
+            WalkBuilder::new(&walk_dir)
+                .threads(40)
+                .build_parallel()
+                .run(|| Box::new(|_| panic!("oops!")));
+        }));
+        let _ = tx.send(result);
+    });
+
+    let outcome = rx.recv_timeout(HANG_TIMEOUT);
+    let _ = fs::remove_dir_all(&dir);
+
+    match outcome {
+        Err(RecvTimeoutError::Timeout) => panic!(
+            "HANG: WalkParallel::run() had not returned or panicked {:?} \
+             after the visitor panicked",
+            HANG_TIMEOUT
+        ),
+        Err(RecvTimeoutError::Disconnected) => {
+            panic!("walker thread died without reporting a result")
+        }
+        Ok(Ok(())) => panic!(
+            "WalkParallel::run() returned normally; the visitor's panic \
+             was swallowed instead of propagated"
+        ),
+        Ok(Err(payload)) => {
+            let msg = payload_message(&*payload);
+            assert!(
+                msg.contains("oops!"),
+                "WalkParallel::run() panicked, but not with the visitor's \
+                 panic (got {:?}, expected it to contain \"oops!\")",
+                msg
+            );
+        }
+    }
+}
